import React, { useState, useEffect, useRef } from 'react';
import ChatMessage from './components/ChatMessage';
import InputBar from './components/InputBar';
import { detectAdversarial, correctPrompt, queryLLM } from './services/api';
import './App.css';

function App() {
  const [messages, setMessages] = useState([]);
  const [inputText, setInputText] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const bottomRef = useRef(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    const prompt = inputText.trim();
    if (!prompt) return;

    setMessages((prev) => [...prev, { sender: 'user', text: prompt }]);
    setInputText('');
    setIsLoading(true);

    try {
      const detection = await detectAdversarial(prompt);
      if (detection.isAdversarial) {
        setMessages((prev) => [...prev, { sender: 'bot', text: '🔒 Adversarial prompt detected. Correcting...' }]);
        const correction = await correctPrompt(prompt);
        setMessages((prev) => [...prev, { sender: 'bot', text: `✏️ Corrected Prompt:\n${correction.correctedPrompt}` }]);
        const llmRes = await queryLLM(correction.correctedPrompt);
        setMessages((prev) => [...prev, { sender: 'bot', text: llmRes.response }]);
      } else {
        const llmRes = await queryLLM(prompt);
        setMessages((prev) => [...prev, { sender: 'bot', text: llmRes.response }]);
      }
    } catch {
      setMessages((prev) => [...prev, { sender: 'bot', text: '❌ Something went wrong.' }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="app">
      <header className="app-header">Adversarial Chat Interface</header>
      <main className="chat-container">
        {messages.map((msg, idx) => (
          <ChatMessage key={idx} sender={msg.sender} text={msg.text} />
        ))}
        <div ref={bottomRef} />
      </main>
      <footer className="input-footer">
        <InputBar
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
          onSubmit={handleSubmit}
          isLoading={isLoading}
        />
      </footer>
    </div>
  );
}

export default App;
